  'edit.stateHint': 'این کار اینجا به یاد می‌آورد که دو طرف آخرین بار بر سر چه توافق کردند. برای هر کار یک پرونده. از دست دادنش چیزی را ویران نمی‌کند اما کار را بسیار به عقب می‌برد.',
  'edit.scheduleHint': 'چه زمانی این کار خودبه‌خود اجرا می‌شود. دستی یعنی فقط وقتی از روی کارت آن شروعش کنید. زمان واقعی ظرف چند ثانیه به تغییر واکنش نشان می‌دهد. هر N، هر روز و روزهای هفته به ساعت پایبندند. Cron برای ریتمی است که انتخابگرها نمی‌توانند بیانش کنند و در منطقه زمانی این دستگاه خوانده می‌شود.',
  'edit.excludeHint': 'در هر سطر یک الگو. نام پرونده‌های نیمه‌نوشته همیشه کنار گذاشته می‌شوند، هرچه اینجا نوشته باشید.',
  'edit.excludeSets': 'فهرست‌های مشترک',
  'edit.excludeSetsHint': 'فهرست‌هایی که یک بار در تنظیمات تعریف می‌شوند. آنچه اینجا انتخاب می‌کنی به الگوهای خودِ این کار در پایین افزوده می‌شود و جای آن‌ها را نمی‌گیرد.',
  'edit.quietHint': 'یک پرونده چه مدت باید بدون تغییر بماند تا یک اجرا سراغش برود. این جلوی کپی شدن پرونده نیمه‌نوشته را در میانه نوشتن می‌گیرد. پیش‌فرض پنج ثانیه است و خالی یعنی بی‌درنگ. با زمان آرامش در حالت زمان واقعی اشتباه نگیرید: آن برای کل پوشه شمرده می‌شود.',
  'edit.runAtStart': 'همگام‌سازی بلافاصله پس از شروع برنامه',
  'edit.emptyDirsHint': 'پوشه‌ای که پرونده در آن هست به هر حال منتقل می‌شود. پوشهٔ خالی چیزی ندارد که بر آن دلالت کند، پس به ثبت جداگانه نیاز دارد. برای سطل ذخیره‌سازی که پوشهٔ واقعی ندارد خاموشش کنید.',
  'edit.metadataHint': 'دسترسی‌ها، مالک و ویژگی‌های گسترده همراه داده‌ها می‌روند، هرجا که هر دو طرف بتوانند نگهشان دارند.',
