  'update.auto': 'به‌روزرسانی خودکار',
  'update.autoHint': 'ArrowLoop روزی یک بار به دنبال نسخهٔ تازه می‌گردد، آن را در پس‌زمینه دانلود می‌کند و با چک‌سام‌هایی که همراه انتشار منتشر شده‌اند بررسی می‌کند. نسخهٔ تازه دفعهٔ بعد که ArrowLoop را اجرا کنید به کار می‌افتد، پس همگام‌سازی در حال اجرا قطع نمی‌شود. نسخهٔ نصب‌شده و نسخهٔ قابل‌حمل هر دو در همان جایی که هستند به‌روز می‌شوند.',
