  'edit.trashHint': 'حذف به جابه‌جایی به پوشه‌ای پنهان به نام ‎.arrowloop درون درخت همگام‌شده تبدیل می‌شود، پس هیچ کاری که این کار انجام می‌دهد چیزی را برای همیشه نابود نمی‌کند و پرونده‌ای که اشتباهی حذف شده از زبانهٔ سطل زباله بازمی‌گردد. آن پوشه را هر کسی که از اشتراک استفاده می‌کند می‌بیند، و دقیقاً همین دلیل خاموش کردن این گزینه است: بدون سطل زباله هرگز ساخته نمی‌شود، حذف قطعی است، و سمت بازنده یک تعارض هم همین‌طور. برای پوشه دانلود منطقی، برای پوشه اسناد فکر بدی است.',
  'edit.newerWins': 'در تعارض، نسخهٔ جدیدتر برنده است',
