  // The phone.
  //
  // Android's own questions, which the container has no equivalent for: a
  // permission granted on a settings page, a schedule that waits for the
  // charger, a doze rule that turns a nightly job into a suggestion. They
  // live in the SAME table as everything else, because one German is one
  // German and a second table would drift from the first.
  'phone.access': 'دسترسی به فایل‌ها',
  'phone.permissionHint': 'این کلید در اختیار اندروید است. لمس آن صفحه‌ای را باز می‌کند که اجازه در آن داده یا پس گرفته می‌شود.',
  'phone.accessNone': 'این نسخهٔ اندروید چنین اجازه‌ای را نمی‌شناسد، بنابراین پوشه‌ها باید یکی‌یکی سپرده شوند.',
  'phone.appData': 'Android/data',
  'phone.appDataHint': 'هر پوشه در Android/data به یک برنامه تعلق دارد و از Android 11 به بعد هیچ برنامهٔ دیگری اجازه ندارد داخل آن را ببیند، حتی ArrowLoop. روی گوشی روت‌شده ArrowLoop آنجا می‌خواند و می‌نویسد؛ با Shizuku فقط می‌تواند بخواند. وقتی این کلید روشن باشد، پوشه‌ها به‌صورت مقصدی به نام Android نمایش داده می‌شوند.',
  'phone.appDataRoot': 'از طریق روت، ArrowLoop این پوشه‌ها را می‌خواند و در آن‌ها می‌نویسد.',
