  'opt.icloudTrustHint': 'Apple فقط با توکن اعتماد ورودی که با کد ارسال‌شده به دستگاه‌هایتان تأیید کرده‌اید به rclone اجازه ورود می‌دهد. روی یک رایانه با rclone config یک remote برای iCloud Drive بسازید و trust_token و cookies را از بخش آن در rclone.conf در این فیلدها کپی کنید. پس از ۳۰ روز Apple دوباره می‌پرسد: آنجا rclone config reconnect را اجرا کنید و هر دو را از نو بچسبانید.',
