  'new.change.welcomeMotion': 'در نصب تازه، صفحه خوش‌آمد سه گام خود را با رنگ تأکیدی نشان می‌دهد و آن‌ها را مثل صحنه‌ای کوچک اجرا می‌کند: یک نشانگر مقصدی اضافه می‌کند، کاری می‌سازد و نخستین همگام‌سازی را اجرا می‌کند.',
  'new.change.titleBar': 'برنامه دسکتاپ نوار عنوان خودش را در Windows و Linux می‌کشد، با ظاهری که انتخاب کرده‌ای.',
  'new.change.unreadFolders': 'پوشه‌ای که ArrowLoop اجازهٔ باز کردنش را ندارد، یا هنگام خواندن ناپدید می‌شود، دیگر اجرا را متوقف نمی‌کند. اجرا آن را در هر دو طرف دست‌نخورده می‌گذارد و در جزئیات اجرا نامش را می‌آورد.',
  'new.change.settingsTiles': '{settings} ستونی از کاشی‌هاست و هر کاشی همهٔ کارت‌هایش را نشان می‌دهد. آنچه در {engine} بود حالا زیر {general}، {sync} و {safety} است.',
  'new.change.anomaliesModule': 'کلیدی برای {anomalies} در {safety} یادداشت‌ها و صفحه‌شان را خاموش می‌کند. ترمزها همچنان نگه می‌دارند و آن‌وقت به اجرای نگه‌داشته در کار خودش پاسخ داده می‌شود.',
  'new.change.infoTile': '{info} همهٔ نسخه‌ها را فهرست می‌کند و به‌روزرسانی‌هایشان را بررسی می‌کند. کارت {help} راهنمای کاربر و گزارش خطا را اضافه می‌کند.',
  'new.change.loginReset': 'گذرواژهٔ فراموش‌شده را می‌توان از صفحهٔ ورود با کدی از گزارش کانتینر بازنشانی کرد.',
  'new.change.notifyChannels': '{notifications} در {safety} اکنون با ایمیل و به Discord، Slack، Gotify، ntfy، یک سرور Apprise و Healthchecks.io هم می‌فرستد، هر کدام با کلید خود و یک دکمهٔ آزمایش.',
  'new.change.notifyTile': '{notifications} در تنظیمات کاشی خودش را دارد.',
  'new.change.automationStart': 'Tasker، MacroDroid و دیگر برنامه‌های خودکارسازی می‌توانند یک کار را روی گوشی شروع کنند، یا همهٔ کارها را با هم.',
  'new.change.trustedWifi': 'روی گوشی، یک VPN می‌تواند بگذارد کارهایش در شبکه‌های wifi مورد اعتمادت، مثل wifi خانه، مستقیم وصل شوند.',
  'new.change.signIn': 'با Pocket ID یا سرویس ورود دیگری وارد شوید. آن را در کاشی امنیت اضافه کنید تا صفحه ورود دکمه‌ای برایش داشته باشد.',
  'new.change.apiTokens': 'توکن‌های API برای داشبوردها و اسکریپت‌ها: یکی که وضعیت و گزارش را می‌خواند، یا یکی برای همه‌چیز. توکن‌های خواندن شما همچنان کار می‌کنند.',
  'new.change.sessions': 'ورود پس از راه‌اندازی دوباره هم می‌ماند و کارت نشست‌ها هر مرورگرِ واردشده را نشان می‌دهد تا بتوانید آن را خارج کنید.',
  'new.change.passwordQuestion': 'اگر مدتی پیش وارد شده‌اید، ArrowLoop پیش از یک تغییر حساس رمز عبورتان را می‌پرسد، به جای اینکه شما را خارج کند.',
  'new.change.publicUrl': 'کلیدهای عبور و سرویس‌های ورود به نشانی‌ای نیاز دارند که ArrowLoop را با آن باز می‌کنید. آن را با ARROWLOOP_PUBLIC_URL تنظیم کنید.',
